package com.civicpulse.service; import com.civicpulse.entity.*; import com.civicpulse.repository.NotificationRepository; import org.springframework.stereotype.Service;
@Service public class NotificationService {private final NotificationRepository repo; public NotificationService(NotificationRepository repo){this.repo=repo;} public void notify(User user,Complaint complaint,String title,String message){Notification n=new Notification();n.setUser(user);n.setComplaint(complaint);n.setTitle(title);n.setMessage(message);repo.save(n);}}
